declare
 j constant jsonb := $payload$[{"id":"835f1de3-70b7-4d41-a9ff-1695b7ae21fc","recipe_group_id":"8686de2f-500a-4c72-8f1c-1e9c0341e905","language":"es","slug":"receta-de-bandeja-paisa","public_path":"/receta-de-bandeja-paisa","total_time_minutes":675,"summary":"Esta bandeja paisa reúne en un solo plato los componentes más reconocibles de la preparación antioqueña: frijoles rojos espesos, arroz blanco, arepa, carne molida, chicharrón, chorizo, tajadas de plátano maduro, huevo frito, aguacate y hogao.\n\nLa propuesta rinde 4 bandejas abundantes. Requiere 45 minutos de preparación, unos 150 minutos de cocción y 8–12 horas de remojo de los frijoles: entre 675 y 915 minutos en total. La ficha muestra el mínimo de 675 minutos, incluido el remojo de 8 horas; varias tareas de cocina se hacen en paralelo. Las cantidades, tiempos, absorción de aceite y rendimiento están pendientes de confirmación mediante prueba de cocina.","content_html":"<p>Esta bandeja paisa reúne en un solo plato los componentes más reconocibles de la preparación antioqueña: frijoles rojos espesos, arroz blanco, arepa, carne molida, chicharrón, chorizo, tajadas de plátano maduro, huevo frito, aguacate y hogao.</p><p>La propuesta rinde 4 bandejas abundantes. Requiere 45 minutos de preparación, unos 150 minutos de cocción y 8–12 horas de remojo de los frijoles: entre 675 y 915 minutos en total. La ficha muestra el mínimo de 675 minutos, incluido el remojo de 8 horas; varias tareas de cocina se hacen en paralelo. Las cantidades, tiempos, absorción de aceite y rendimiento están pendientes de confirmación mediante prueba de cocina.</p>","steps":[{"title":"Remoja los frijoles","content":"Revisa y enjuaga 200 g de frijoles rojos secos. Cúbrelos con abundante agua fría y déjalos 8–12 horas en la nevera. Escurre y desecha el agua de remojo. El total mínimo de 675 minutos incluye 8 horas de remojo; con 12 horas de remojo, calcula 915 minutos en total.","image_url":"/recetas/receta-de-bandeja-paisa/paso-01.webp","image_alt":"Bandeja paisa: frijoles rojos secos cubiertos con agua para el remojo"},{"title":"Cuece los frijoles hasta que estén tiernos","content":"Pon los frijoles escurridos en una olla con 1 litro de agua limpia. Lleva a ebullición, retira la espuma, baja a fuego medio-bajo y cocina parcialmente tapados 90–120 minutos. Remueve cada 20 minutos y añade agua caliente si dejan de estar cubiertos. Están listos cuando se aplastan con facilidad pero conservan la forma; no añadas todavía tomate ni sal.","image_url":"/recetas/receta-de-bandeja-paisa/paso-02.webp","image_alt":"Bandeja paisa: frijoles rojos cociéndose suavemente en una olla"},{"title":"Prepara el hogao","content":"Mientras se cuecen los frijoles, calienta 15 g del aceite en una sartén a fuego medio. Añade 160 g de cebolla picada y cocina 5 minutos. Incorpora 12 g de ajo picado y 1 g de comino; remueve 30 segundos. Agrega 300 g de tomate picado y 2 g de sal. Cocina 12–15 minutos, hasta obtener una salsa espesa. Reserva 40 g para los frijoles y mantén el resto para servir.","image_url":"/recetas/receta-de-bandeja-paisa/paso-03.webp","image_alt":"Bandeja paisa: hogao espeso de tomate y cebolla en una sartén"},{"title":"Termina los frijoles","content":"Cuando los frijoles estén tiernos, añade los 40 g de hogao reservados y 2 g de sal. Cocina destapado 10 minutos a fuego bajo, removiendo, hasta que el caldo cubra la cuchara. Si están muy secos, añade agua caliente de 30 en 30 ml; si están caldosos, prolonga la reducción.","image_url":"/recetas/receta-de-bandeja-paisa/paso-04.webp","image_alt":"Bandeja paisa: frijoles rojos terminados con hogao y caldo espeso"},{"title":"Cocina el arroz","content":"Enjuaga 200 g de arroz blanco hasta que el agua salga casi clara. Ponlo en una olla con 400 ml de agua y 2 g de sal. Lleva a ebullición, tapa, baja al mínimo y cocina 15–18 minutos sin destapar. Apaga y deja reposar 10 minutos; separa los granos con un tenedor.","image_url":"/recetas/receta-de-bandeja-paisa/paso-05.webp","image_alt":"Bandeja paisa: arroz blanco cocido y suelto en una olla"},{"title":"Forma y asa las arepas","content":"Mezcla 120 g de harina de maíz precocida con 240 ml de agua tibia y 1 g de sal. Reposa 5 minutos. Divide en 4 porciones, forma discos de unos 9 cm de diámetro y 1 cm de grosor y alisa los bordes. Asa en plancha ligeramente aceitada 6–8 minutos por lado a fuego medio-bajo, hasta que estén firmes y doradas.","image_url":"/recetas/receta-de-bandeja-paisa/paso-06.webp","image_alt":"Bandeja paisa: cuatro arepas pequeñas dorándose en una plancha"},{"title":"Dora el chicharrón","content":"Corta 240 g de panceta de cerdo con piel en 4 tiras iguales y haz cortes superficiales en la piel sin separar las piezas. Ponlas en una sartén fría con 60 ml de agua, tapa y cocina 10 minutos a fuego medio. Destapa y continúa 20–30 minutos a fuego medio-bajo, girando, mientras se evapora el agua y se funde la grasa. Retira cuando la piel esté crujiente, la carne dorada y el centro alcance al menos 71 °C. Escurre en rejilla; guarda la grasa aparte, no la viertas por el desagüe.","image_url":"/recetas/receta-de-bandeja-paisa/paso-07.webp","image_alt":"Bandeja paisa: tiras de chicharrón doradas y crujientes en una sartén"},{"title":"Cocina la carne y los chorizos","content":"Calienta 10 g del aceite en una sartén limpia. Añade 260 g de carne molida y 1 g de sal; cocina 7–9 minutos a fuego medio-alto, separándola, hasta que no queden zonas rosadas y alcance 71 °C. Retira y mantén caliente. En la misma sartén cocina 4 chorizos pequeños, 200 g en total, durante 10–12 minutos, girándolos, hasta que alcancen 71 °C en el centro.","image_url":"/recetas/receta-de-bandeja-paisa/paso-08.webp","image_alt":"Bandeja paisa: carne molida dorada y cuatro chorizos cocinándose"},{"title":"Fríe el plátano y los huevos","content":"Corta 400 g de plátano maduro pelado en tajadas diagonales. Calienta el aceite restante en una sartén amplia y fríe las tajadas 3–4 minutos por lado a fuego medio, hasta que estén doradas y tiernas; escurre sobre rejilla. En la misma sartén fríe 4 huevos, uno por uno, 3–4 minutos, hasta que la clara esté completamente cuajada. Para embarazadas, niños pequeños, mayores o personas inmunodeprimidas, cocina también la yema hasta que esté firme.","image_url":"/recetas/receta-de-bandeja-paisa/paso-09.webp","image_alt":"Bandeja paisa: tajadas de plátano maduro doradas y huevos fritos con clara cuajada"},{"title":"Monta las cuatro bandejas","content":"Reparte en cada plato una cuarta parte de los frijoles y del arroz, 1 arepa, 1 tira de chicharrón, 1 chorizo, una cuarta parte de la carne molida y del plátano, 1 huevo y 50 g de aguacate. Añade el hogao restante al gusto y sirve inmediatamente. Las cantidades, tiempos y rendimiento son una propuesta editorial pendiente de confirmación en cocina.","image_url":"/recetas/receta-de-bandeja-paisa/paso-10.webp","image_alt":"Bandeja paisa completa con frijoles, arroz, arepa, carnes, plátano, huevo, aguacate y hogao"}]},{"id":"c50bd0e3-f8cd-59d6-ad26-8d357e17b95c","recipe_group_id":"8686de2f-500a-4c72-8f1c-1e9c0341e905","language":"de","slug":"bandeja-paisa-kolumbianischer-teller","public_path":"/de/bandeja-paisa-kolumbianischer-teller","total_time_minutes":675,"summary":"Diese Bandeja paisa vereint die bekanntesten Bestandteile des Gerichts aus Antioquia auf einem Teller: sämige rote Bohnen, weißen Reis, eine Arepa, Rinderhack, knusprigen Schweinebauch, Chorizo, reife Kochbananenscheiben, Spiegelei, Avocado und Hogao.\n\nDer Vorschlag ergibt 4 großzügige Portionen. Vorgesehen sind 45 Minuten Vorbereitung, etwa 150 Minuten Garzeit und 8–12 Stunden Einweichzeit für die Bohnen: insgesamt 675 bis 915 Minuten. Die Rezeptkarte zeigt den Mindestwert von 675 Minuten einschließlich 8 Stunden Einweichen; mehrere Küchenarbeiten laufen parallel. Mengen, Zeiten, Ölaufnahme und Ausbeute müssen noch durch einen Kochtest bestätigt werden.","content_html":"<p>Diese Bandeja paisa vereint die bekanntesten Bestandteile des Gerichts aus Antioquia auf einem Teller: sämige rote Bohnen, weißen Reis, eine Arepa, Rinderhack, knusprigen Schweinebauch, Chorizo, reife Kochbananenscheiben, Spiegelei, Avocado und Hogao.</p><p>Der Vorschlag ergibt 4 großzügige Portionen. Vorgesehen sind 45 Minuten Vorbereitung, etwa 150 Minuten Garzeit und 8–12 Stunden Einweichzeit für die Bohnen: insgesamt 675 bis 915 Minuten. Die Rezeptkarte zeigt den Mindestwert von 675 Minuten einschließlich 8 Stunden Einweichen; mehrere Küchenarbeiten laufen parallel. Mengen, Zeiten, Ölaufnahme und Ausbeute müssen noch durch einen Kochtest bestätigt werden.</p>","steps":[{"title":"Bohnen einweichen","content":"200 g getrocknete rote Kidneybohnen verlesen und abspülen. Mit reichlich kaltem Wasser bedecken und 8–12 Stunden im Kühlschrank einweichen. Abgießen und das Einweichwasser entsorgen. Die Mindestgesamtzeit von 675 Minuten enthält 8 Stunden Einweichen; bei 12 Stunden Einweichen insgesamt 915 Minuten einplanen.","image_url":"/recetas/receta-de-bandeja-paisa/paso-01.webp","image_alt":"Bandeja paisa: getrocknete rote Bohnen im Einweichwasser"},{"title":"Bohnen weich kochen","content":"Die abgetropften Bohnen mit 1 Liter frischem Wasser in einen Topf geben. Aufkochen, Schaum abschöpfen, auf mittlere bis niedrige Hitze reduzieren und mit teilweise aufgelegtem Deckel 90–120 Minuten garen. Alle 20 Minuten umrühren und heißes Wasser ergänzen, wenn die Bohnen nicht mehr bedeckt sind. Sie sind fertig, wenn sie sich leicht zerdrücken lassen, aber ihre Form halten; Tomate und Salz noch nicht zugeben.","image_url":"/recetas/receta-de-bandeja-paisa/paso-02.webp","image_alt":"Bandeja paisa: rote Bohnen garen sanft im Topf"},{"title":"Hogao zubereiten","content":"Während die Bohnen garen, 15 g des Öls in einer Pfanne bei mittlerer Hitze erwärmen. 160 g gehackte Zwiebel zugeben und 5 Minuten garen. 12 g gehackten Knoblauch und 1 g Kreuzkümmel zugeben; 30 Sekunden rühren. 300 g gehackte Tomaten und 2 g Salz hinzufügen. 12–15 Minuten zu einer dicken Sauce einkochen. 40 g für die Bohnen zurückbehalten, den Rest zum Servieren aufheben.","image_url":"/recetas/receta-de-bandeja-paisa/paso-03.webp","image_alt":"Bandeja paisa: dickes Tomaten-Zwiebel-Hogao in einer Pfanne"},{"title":"Bohnen fertigstellen","content":"Zu den weichen Bohnen die zurückbehaltenen 40 g Hogao und 2 g Salz geben. Offen bei niedriger Hitze 10 Minuten unter Rühren garen, bis die Brühe einen Löffel überzieht. Sind sie zu trocken, heißes Wasser in 30-ml-Schritten ergänzen; sind sie zu flüssig, länger einkochen.","image_url":"/recetas/receta-de-bandeja-paisa/paso-04.webp","image_alt":"Bandeja paisa: fertige rote Bohnen mit Hogao und sämiger Brühe"},{"title":"Reis kochen","content":"200 g weißen Reis spülen, bis das Wasser fast klar ist. Mit 400 ml Wasser und 2 g Salz in einen Topf geben. Aufkochen, abdecken, auf kleinste Hitze stellen und 15–18 Minuten garen, ohne den Deckel zu öffnen. Herd ausschalten, 10 Minuten ruhen lassen und mit einer Gabel auflockern.","image_url":"/recetas/receta-de-bandeja-paisa/paso-05.webp","image_alt":"Bandeja paisa: locker gegarter weißer Reis im Topf"},{"title":"Arepas formen und braten","content":"120 g vorgegartes Maismehl mit 240 ml lauwarmem Wasser und 1 g Salz mischen. 5 Minuten ruhen lassen. In 4 Portionen teilen, etwa 9 cm breite und 1 cm dicke Scheiben formen und die Ränder glätten. Auf einer leicht geölten Grillplatte bei mittlerer bis niedriger Hitze 6–8 Minuten je Seite garen, bis sie fest und goldbraun sind.","image_url":"/recetas/receta-de-bandeja-paisa/paso-06.webp","image_alt":"Bandeja paisa: vier kleine Arepas bräunen auf einer Grillplatte"},{"title":"Schweinebauch knusprig braten","content":"240 g Schweinebauch mit Schwarte in 4 gleich große Streifen schneiden und die Schwarte flach einschneiden, ohne die Stücke zu durchtrennen. Mit 60 ml Wasser in eine kalte Pfanne geben, abdecken und bei mittlerer Hitze 10 Minuten garen. Offen bei mittlerer bis niedriger Hitze weitere 20–30 Minuten unter Wenden garen, während Wasser verdampft und Fett austritt. Herausnehmen, wenn die Schwarte knusprig, das Fleisch goldbraun und die Kerntemperatur mindestens 71 °C ist. Auf einem Gitter abtropfen lassen; Fett separat auffangen und nicht in den Abfluss gießen.","image_url":"/recetas/receta-de-bandeja-paisa/paso-07.webp","image_alt":"Bandeja paisa: goldbraune knusprige Schweinebauchstreifen in einer Pfanne"},{"title":"Hackfleisch und Chorizos garen","content":"10 g des Öls in einer sauberen Pfanne erhitzen. 260 g Rinderhack und 1 g Salz zugeben; bei mittlerer bis hoher Hitze 7–9 Minuten unter Zerteilen braten, bis keine rosa Stellen mehr vorhanden sind und 71 °C erreicht werden. Herausnehmen und warm halten. In derselben Pfanne 4 kleine Chorizos, insgesamt 200 g, 10–12 Minuten unter Wenden garen, bis sie im Kern 71 °C erreichen.","image_url":"/recetas/receta-de-bandeja-paisa/paso-08.webp","image_alt":"Bandeja paisa: gebräuntes Rinderhack und vier Chorizos beim Garen"},{"title":"Kochbanane und Eier braten","content":"400 g geschälte reife Kochbanane schräg in Scheiben schneiden. Das restliche Öl in einer breiten Pfanne erhitzen und die Scheiben bei mittlerer Hitze 3–4 Minuten je Seite goldbraun und weich braten; auf einem Gitter abtropfen lassen. In derselben Pfanne 4 Eier einzeln 3–4 Minuten braten, bis das Eiweiß vollständig gestockt ist. Für Schwangere, kleine Kinder, ältere oder immungeschwächte Menschen auch das Eigelb fest garen.","image_url":"/recetas/receta-de-bandeja-paisa/paso-09.webp","image_alt":"Bandeja paisa: goldbraune Kochbananenscheiben und Spiegeleier mit festem Eiweiß"},{"title":"Vier Teller anrichten","content":"Auf jeden Teller ein Viertel der Bohnen und des Reises, 1 Arepa, 1 Streifen knusprigen Schweinebauch, 1 Chorizo, ein Viertel des Hackfleischs und der Kochbanane, 1 Ei und 50 g Avocado geben. Übriges Hogao nach Geschmack zugeben und sofort servieren. Mengen, Zeiten und Ausbeute sind ein redaktioneller Vorschlag, der noch in der Küche bestätigt werden muss.","image_url":"/recetas/receta-de-bandeja-paisa/paso-10.webp","image_alt":"Vollständige Bandeja paisa mit Bohnen, Reis, Arepa, Fleisch, Kochbanane, Ei, Avocado und Hogao"}]},{"id":"6857b59b-7f19-5cd9-a3cc-930700c6932e","recipe_group_id":"8686de2f-500a-4c72-8f1c-1e9c0341e905","language":"en","slug":"bandeja-paisa-colombian-platter","public_path":"/en/bandeja-paisa-colombian-platter","total_time_minutes":675,"summary":"This bandeja paisa brings the best-known components of the Antioquian dish together on one platter: thick red beans, white rice, an arepa, ground beef, pork crackling, chorizo, ripe plantain slices, a fried egg, avocado and hogao.\n\nThe proposal makes 4 generous platters. Allow 45 minutes of preparation, about 150 minutes of cooking and 8–12 hours to soak the beans: 675 to 915 minutes overall. The recipe card shows the minimum of 675 minutes, including an 8-hour soak; several cooking tasks run in parallel. Quantities, times, oil absorption and yield await confirmation through a kitchen test.","content_html":"<p>This bandeja paisa brings the best-known components of the Antioquian dish together on one platter: thick red beans, white rice, an arepa, ground beef, pork crackling, chorizo, ripe plantain slices, a fried egg, avocado and hogao.</p><p>The proposal makes 4 generous platters. Allow 45 minutes of preparation, about 150 minutes of cooking and 8–12 hours to soak the beans: 675 to 915 minutes overall. The recipe card shows the minimum of 675 minutes, including an 8-hour soak; several cooking tasks run in parallel. Quantities, times, oil absorption and yield await confirmation through a kitchen test.</p>","steps":[{"title":"Soak the beans","content":"Sort and rinse 200 g of dried red kidney beans. Cover with plenty of cold water and refrigerate for 8–12 hours. Drain and discard the soaking water. The minimum total of 675 minutes includes an 8-hour soak; with a 12-hour soak, allow 915 minutes overall.","image_url":"/recetas/receta-de-bandeja-paisa/paso-01.webp","image_alt":"Bandeja paisa: dried red beans covered with soaking water"},{"title":"Cook the beans until tender","content":"Put the drained beans in a pot with 1 litre of clean water. Bring to a boil, skim off the foam, reduce to medium-low heat and cook partly covered for 90–120 minutes. Stir every 20 minutes and add hot water if the beans are no longer covered. They are ready when they mash easily but still hold their shape; do not add tomato or salt yet.","image_url":"/recetas/receta-de-bandeja-paisa/paso-02.webp","image_alt":"Bandeja paisa: red beans gently cooking in a pot"},{"title":"Make the hogao","content":"While the beans cook, heat 15 g of the oil in a frying pan over medium heat. Add 160 g of chopped onion and cook for 5 minutes. Add 12 g of chopped garlic and 1 g of cumin; stir for 30 seconds. Add 300 g of chopped tomato and 2 g of salt. Cook for 12–15 minutes until thick. Reserve 40 g for the beans and keep the rest for serving.","image_url":"/recetas/receta-de-bandeja-paisa/paso-03.webp","image_alt":"Bandeja paisa: thick tomato and onion hogao in a frying pan"},{"title":"Finish the beans","content":"When the beans are tender, add the reserved 40 g of hogao and 2 g of salt. Cook uncovered over low heat for 10 minutes, stirring, until the broth coats a spoon. If too dry, add hot water in 30 ml increments; if too soupy, reduce for longer.","image_url":"/recetas/receta-de-bandeja-paisa/paso-04.webp","image_alt":"Bandeja paisa: finished red beans with hogao and thick broth"},{"title":"Cook the rice","content":"Rinse 200 g of white rice until the water is almost clear. Place in a pot with 400 ml of water and 2 g of salt. Bring to a boil, cover, reduce to the lowest heat and cook for 15–18 minutes without lifting the lid. Turn off the heat and rest for 10 minutes; fluff with a fork.","image_url":"/recetas/receta-de-bandeja-paisa/paso-05.webp","image_alt":"Bandeja paisa: fluffy cooked white rice in a pot"},{"title":"Shape and griddle the arepas","content":"Mix 120 g of precooked corn flour with 240 ml of warm water and 1 g of salt. Rest for 5 minutes. Divide into 4 portions, shape into discs about 9 cm across and 1 cm thick, and smooth the edges. Cook on a lightly oiled griddle over medium-low heat for 6–8 minutes per side, until firm and golden.","image_url":"/recetas/receta-de-bandeja-paisa/paso-06.webp","image_alt":"Bandeja paisa: four small arepas browning on a griddle"},{"title":"Brown the pork crackling","content":"Cut 240 g of skin-on pork belly into 4 equal strips and score the skin shallowly without separating the pieces. Place in a cold frying pan with 60 ml of water, cover and cook over medium heat for 10 minutes. Uncover and continue over medium-low heat for 20–30 minutes, turning, while the water evaporates and the fat renders. Remove when the skin is crisp, the meat is golden and the centre reaches at least 71 °C. Drain on a rack; collect the fat separately and do not pour it down the drain.","image_url":"/recetas/receta-de-bandeja-paisa/paso-07.webp","image_alt":"Bandeja paisa: golden crisp pork-crackling strips in a frying pan"},{"title":"Cook the beef and chorizo","content":"Heat 10 g of the oil in a clean frying pan. Add 260 g of ground beef and 1 g of salt; cook over medium-high heat for 7–9 minutes, breaking it up, until no pink areas remain and it reaches 71 °C. Remove and keep warm. In the same pan, cook 4 small chorizo sausages, 200 g total, for 10–12 minutes, turning, until their centres reach 71 °C.","image_url":"/recetas/receta-de-bandeja-paisa/paso-08.webp","image_alt":"Bandeja paisa: browned ground beef and four cooking chorizo sausages"},{"title":"Fry the plantain and eggs","content":"Cut 400 g of peeled ripe plantain into diagonal slices. Heat the remaining oil in a wide frying pan and fry the slices over medium heat for 3–4 minutes per side until golden and tender; drain on a rack. In the same pan fry 4 eggs, one at a time, for 3–4 minutes until the whites are completely set. For pregnant people, young children, older adults or immunocompromised people, also cook the yolks until firm.","image_url":"/recetas/receta-de-bandeja-paisa/paso-09.webp","image_alt":"Bandeja paisa: golden ripe plantain slices and fried eggs with set whites"},{"title":"Assemble the four platters","content":"Put one quarter of the beans and rice, 1 arepa, 1 strip of pork crackling, 1 chorizo, one quarter of the beef and plantain, 1 egg and 50 g of avocado on each plate. Add the remaining hogao to taste and serve immediately. Quantities, times and yield are an editorial proposal awaiting confirmation in the kitchen.","image_url":"/recetas/receta-de-bandeja-paisa/paso-10.webp","image_alt":"Complete bandeja paisa with beans, rice, arepa, meats, plantain, egg, avocado and hogao"}]},{"id":"647e43c1-a9d5-5fd4-8b6d-fabdada6a31c","recipe_group_id":"8686de2f-500a-4c72-8f1c-1e9c0341e905","language":"fr","slug":"bandeja-paisa-assiette-colombienne","public_path":"/fr/bandeja-paisa-assiette-colombienne","total_time_minutes":675,"summary":"Cette bandeja paisa réunit dans une seule assiette les éléments les plus reconnaissables de la cuisine d’Antioquia : haricots rouges épais, riz blanc, arepa, bœuf haché, poitrine de porc croustillante, chorizo, tranches de banane plantain mûre, œuf au plat, avocat et hogao.\n\nLa proposition donne 4 assiettes généreuses. Comptez 45 minutes de préparation, environ 150 minutes de cuisson et 8–12 heures de trempage des haricots : de 675 à 915 minutes au total. La fiche indique le minimum de 675 minutes, avec 8 heures de trempage ; plusieurs tâches de cuisine se font en parallèle. Quantités, durées, absorption d’huile et rendement attendent confirmation par un essai en cuisine.","content_html":"<p>Cette bandeja paisa réunit dans une seule assiette les éléments les plus reconnaissables de la cuisine d’Antioquia : haricots rouges épais, riz blanc, arepa, bœuf haché, poitrine de porc croustillante, chorizo, tranches de banane plantain mûre, œuf au plat, avocat et hogao.</p><p>La proposition donne 4 assiettes généreuses. Comptez 45 minutes de préparation, environ 150 minutes de cuisson et 8–12 heures de trempage des haricots : de 675 à 915 minutes au total. La fiche indique le minimum de 675 minutes, avec 8 heures de trempage ; plusieurs tâches de cuisine se font en parallèle. Quantités, durées, absorption d’huile et rendement attendent confirmation par un essai en cuisine.</p>","steps":[{"title":"Faire tremper les haricots","content":"Trier et rincer 200 g de haricots rouges secs. Couvrir largement d’eau froide et laisser 8–12 heures au réfrigérateur. Égoutter et jeter l’eau de trempage. Le minimum total de 675 minutes inclut 8 heures de trempage ; avec 12 heures de trempage, comptez 915 minutes au total.","image_url":"/recetas/receta-de-bandeja-paisa/paso-01.webp","image_alt":"Bandeja paisa : haricots rouges secs couverts d’eau de trempage"},{"title":"Cuire les haricots jusqu’à tendreté","content":"Mettre les haricots égouttés dans une casserole avec 1 litre d’eau propre. Porter à ébullition, écumer, baisser à feu moyen-doux et cuire partiellement couvert 90–120 minutes. Remuer toutes les 20 minutes et ajouter de l’eau chaude s’ils ne sont plus immergés. Ils sont prêts lorsqu’ils s’écrasent facilement tout en gardant leur forme ; ne pas encore ajouter de tomate ni de sel.","image_url":"/recetas/receta-de-bandeja-paisa/paso-02.webp","image_alt":"Bandeja paisa : haricots rouges cuisant doucement dans une casserole"},{"title":"Préparer le hogao","content":"Pendant la cuisson des haricots, chauffer 15 g de l’huile dans une poêle à feu moyen. Ajouter 160 g d’oignon haché et cuire 5 minutes. Incorporer 12 g d’ail haché et 1 g de cumin ; remuer 30 secondes. Ajouter 300 g de tomate hachée et 2 g de sel. Cuire 12–15 minutes pour obtenir une sauce épaisse. Réserver 40 g pour les haricots et garder le reste pour le service.","image_url":"/recetas/receta-de-bandeja-paisa/paso-03.webp","image_alt":"Bandeja paisa : hogao épais de tomate et d’oignon dans une poêle"},{"title":"Terminer les haricots","content":"Quand les haricots sont tendres, ajouter les 40 g de hogao réservés et 2 g de sel. Cuire à découvert 10 minutes à feu doux, en remuant, jusqu’à ce que le bouillon nappe la cuillère. S’ils sont trop secs, ajouter de l’eau chaude par portions de 30 ml ; s’ils sont trop liquides, prolonger la réduction.","image_url":"/recetas/receta-de-bandeja-paisa/paso-04.webp","image_alt":"Bandeja paisa : haricots rouges terminés avec hogao et bouillon épais"},{"title":"Cuire le riz","content":"Rincer 200 g de riz blanc jusqu’à ce que l’eau soit presque claire. Mettre dans une casserole avec 400 ml d’eau et 2 g de sel. Porter à ébullition, couvrir, réduire au minimum et cuire 15–18 minutes sans soulever le couvercle. Éteindre et laisser reposer 10 minutes ; détacher les grains à la fourchette.","image_url":"/recetas/receta-de-bandeja-paisa/paso-05.webp","image_alt":"Bandeja paisa : riz blanc cuit et détaché dans une casserole"},{"title":"Former et griller les arepas","content":"Mélanger 120 g de farine de maïs précuite avec 240 ml d’eau tiède et 1 g de sel. Laisser reposer 5 minutes. Diviser en 4 portions, former des disques d’environ 9 cm de diamètre et 1 cm d’épaisseur, puis lisser les bords. Cuire sur une plaque légèrement huilée à feu moyen-doux 6–8 minutes de chaque côté, jusqu’à ce qu’ils soient fermes et dorés.","image_url":"/recetas/receta-de-bandeja-paisa/paso-06.webp","image_alt":"Bandeja paisa : quatre petites arepas dorant sur une plaque"},{"title":"Dorer la poitrine de porc","content":"Couper 240 g de poitrine de porc avec couenne en 4 bandes égales et entailler superficiellement la couenne sans séparer les morceaux. Mettre dans une poêle froide avec 60 ml d’eau, couvrir et cuire 10 minutes à feu moyen. Découvrir et poursuivre 20–30 minutes à feu moyen-doux en retournant, pendant que l’eau s’évapore et que la graisse fond. Retirer lorsque la couenne est croustillante, la viande dorée et le centre à au moins 71 °C. Égoutter sur une grille ; recueillir la graisse à part, sans la verser dans l’évier.","image_url":"/recetas/receta-de-bandeja-paisa/paso-07.webp","image_alt":"Bandeja paisa : bandes de poitrine de porc dorées et croustillantes"},{"title":"Cuire le bœuf et les chorizos","content":"Chauffer 10 g de l’huile dans une poêle propre. Ajouter 260 g de bœuf haché et 1 g de sel ; cuire 7–9 minutes à feu moyen-vif en l’émiettant, jusqu’à disparition des zones roses et jusqu’à 71 °C. Retirer et garder au chaud. Dans la même poêle, cuire 4 petits chorizos, 200 g au total, pendant 10–12 minutes en les retournant, jusqu’à 71 °C au centre.","image_url":"/recetas/receta-de-bandeja-paisa/paso-08.webp","image_alt":"Bandeja paisa : bœuf haché doré et quatre chorizos en cuisson"},{"title":"Frire la banane plantain et les œufs","content":"Couper 400 g de banane plantain mûre épluchée en tranches diagonales. Chauffer le reste d’huile dans une grande poêle et frire les tranches à feu moyen 3–4 minutes par côté, jusqu’à ce qu’elles soient dorées et tendres ; égoutter sur une grille. Dans la même poêle, frire 4 œufs, un par un, 3–4 minutes, jusqu’à ce que le blanc soit entièrement pris. Pour les femmes enceintes, jeunes enfants, personnes âgées ou immunodéprimées, cuire également le jaune jusqu’à ce qu’il soit ferme.","image_url":"/recetas/receta-de-bandeja-paisa/paso-09.webp","image_alt":"Bandeja paisa : banane plantain dorée et œufs frits aux blancs pris"},{"title":"Dresser les quatre assiettes","content":"Mettre sur chaque assiette un quart des haricots et du riz, 1 arepa, 1 bande de poitrine croustillante, 1 chorizo, un quart du bœuf et de la banane plantain, 1 œuf et 50 g d’avocat. Ajouter le hogao restant selon le goût et servir immédiatement. Quantités, durées et rendement constituent une proposition éditoriale à confirmer en cuisine.","image_url":"/recetas/receta-de-bandeja-paisa/paso-10.webp","image_alt":"Bandeja paisa complète avec haricots, riz, arepa, viandes, plantain, œuf, avocat et hogao"}]},{"id":"af83a975-46d3-5abf-adc0-5017f45b69f8","recipe_group_id":"8686de2f-500a-4c72-8f1c-1e9c0341e905","language":"it","slug":"bandeja-paisa-piatto-colombiano","public_path":"/it/bandeja-paisa-piatto-colombiano","total_time_minutes":675,"summary":"Questa bandeja paisa riunisce in un unico piatto gli elementi più riconoscibili della preparazione di Antioquia: fagioli rossi densi, riso bianco, arepa, carne macinata, pancetta croccante, chorizo, fette di platano maturo, uovo fritto, avocado e hogao.\n\nLa proposta dà 4 piatti abbondanti. Prevede 45 minuti di preparazione, circa 150 minuti di cottura e 8–12 ore di ammollo dei fagioli: da 675 a 915 minuti in totale. La scheda mostra il minimo di 675 minuti, incluse 8 ore di ammollo; diverse operazioni di cucina si svolgono in parallelo. Quantità, tempi, assorbimento dell’olio e resa attendono conferma con una prova in cucina.","content_html":"<p>Questa bandeja paisa riunisce in un unico piatto gli elementi più riconoscibili della preparazione di Antioquia: fagioli rossi densi, riso bianco, arepa, carne macinata, pancetta croccante, chorizo, fette di platano maturo, uovo fritto, avocado e hogao.</p><p>La proposta dà 4 piatti abbondanti. Prevede 45 minuti di preparazione, circa 150 minuti di cottura e 8–12 ore di ammollo dei fagioli: da 675 a 915 minuti in totale. La scheda mostra il minimo di 675 minuti, incluse 8 ore di ammollo; diverse operazioni di cucina si svolgono in parallelo. Quantità, tempi, assorbimento dell’olio e resa attendono conferma con una prova in cucina.</p>","steps":[{"title":"Metti in ammollo i fagioli","content":"Controlla e sciacqua 200 g di fagioli rossi secchi. Coprili con abbondante acqua fredda e lasciali 8–12 ore in frigorifero. Scola e scarta l’acqua di ammollo. Il totale minimo di 675 minuti include 8 ore di ammollo; con 12 ore di ammollo, calcola 915 minuti in totale.","image_url":"/recetas/receta-de-bandeja-paisa/paso-01.webp","image_alt":"Bandeja paisa: fagioli rossi secchi coperti d’acqua per l’ammollo"},{"title":"Cuoci i fagioli finché sono teneri","content":"Metti i fagioli scolati in una pentola con 1 litro di acqua pulita. Porta a bollore, elimina la schiuma, abbassa a fuoco medio-basso e cuoci con coperchio parzialmente aperto per 90–120 minuti. Mescola ogni 20 minuti e aggiungi acqua calda se non sono più coperti. Sono pronti quando si schiacciano facilmente ma mantengono la forma; non aggiungere ancora pomodoro o sale.","image_url":"/recetas/receta-de-bandeja-paisa/paso-02.webp","image_alt":"Bandeja paisa: fagioli rossi in cottura dolce nella pentola"},{"title":"Prepara l’hogao","content":"Mentre i fagioli cuociono, scalda 15 g dell’olio in padella a fuoco medio. Aggiungi 160 g di cipolla tritata e cuoci 5 minuti. Unisci 12 g di aglio tritato e 1 g di cumino; mescola 30 secondi. Aggiungi 300 g di pomodoro tritato e 2 g di sale. Cuoci 12–15 minuti fino a ottenere una salsa densa. Tieni da parte 40 g per i fagioli e conserva il resto per servire.","image_url":"/recetas/receta-de-bandeja-paisa/paso-03.webp","image_alt":"Bandeja paisa: hogao denso di pomodoro e cipolla in padella"},{"title":"Completa i fagioli","content":"Quando i fagioli sono teneri, aggiungi i 40 g di hogao tenuti da parte e 2 g di sale. Cuoci senza coperchio 10 minuti a fuoco basso, mescolando, finché il brodo vela il cucchiaio. Se sono troppo asciutti, aggiungi acqua calda in incrementi di 30 ml; se sono troppo liquidi, prosegui la riduzione.","image_url":"/recetas/receta-de-bandeja-paisa/paso-04.webp","image_alt":"Bandeja paisa: fagioli rossi finiti con hogao e brodo denso"},{"title":"Cuoci il riso","content":"Sciacqua 200 g di riso bianco finché l’acqua è quasi limpida. Mettilo in pentola con 400 ml di acqua e 2 g di sale. Porta a bollore, copri, abbassa al minimo e cuoci 15–18 minuti senza aprire. Spegni e lascia riposare 10 minuti; sgrana con una forchetta.","image_url":"/recetas/receta-de-bandeja-paisa/paso-05.webp","image_alt":"Bandeja paisa: riso bianco cotto e sgranato in pentola"},{"title":"Forma e cuoci le arepas","content":"Mescola 120 g di farina di mais precotta con 240 ml di acqua tiepida e 1 g di sale. Lascia riposare 5 minuti. Dividi in 4 porzioni, forma dischi di circa 9 cm di diametro e 1 cm di spessore e liscia i bordi. Cuoci su piastra leggermente oliata a fuoco medio-basso 6–8 minuti per lato, finché sono sodi e dorati.","image_url":"/recetas/receta-de-bandeja-paisa/paso-06.webp","image_alt":"Bandeja paisa: quattro piccole arepas che dorano sulla piastra"},{"title":"Dora il chicharrón","content":"Taglia 240 g di pancetta fresca con cotenna in 4 strisce uguali e incidi superficialmente la cotenna senza separare i pezzi. Metti in una padella fredda con 60 ml di acqua, copri e cuoci 10 minuti a fuoco medio. Scopri e prosegui 20–30 minuti a fuoco medio-basso, girando, mentre l’acqua evapora e il grasso si scioglie. Togli quando la cotenna è croccante, la carne dorata e il centro raggiunge almeno 71 °C. Scola su una griglia; raccogli il grasso a parte e non versarlo nello scarico.","image_url":"/recetas/receta-de-bandeja-paisa/paso-07.webp","image_alt":"Bandeja paisa: strisce di pancetta dorate e croccanti in padella"},{"title":"Cuoci la carne e i chorizo","content":"Scalda 10 g dell’olio in una padella pulita. Aggiungi 260 g di carne macinata e 1 g di sale; cuoci 7–9 minuti a fuoco medio-alto, sgranando, finché non restano zone rosa e raggiunge 71 °C. Togli e tieni al caldo. Nella stessa padella cuoci 4 piccoli chorizo, 200 g in totale, per 10–12 minuti, girandoli, finché raggiungono 71 °C al centro.","image_url":"/recetas/receta-de-bandeja-paisa/paso-08.webp","image_alt":"Bandeja paisa: carne macinata dorata e quattro chorizo in cottura"},{"title":"Friggi platano e uova","content":"Taglia 400 g di platano maturo sbucciato a fette diagonali. Scalda l’olio restante in una padella larga e friggi le fette a fuoco medio 3–4 minuti per lato, finché sono dorate e tenere; scola su una griglia. Nella stessa padella friggi 4 uova, una alla volta, per 3–4 minuti, finché l’albume è completamente rappreso. Per donne in gravidanza, bambini piccoli, anziani o persone immunodepresse, cuoci anche il tuorlo finché è sodo.","image_url":"/recetas/receta-de-bandeja-paisa/paso-09.webp","image_alt":"Bandeja paisa: platano dorato e uova fritte con albume rappreso"},{"title":"Componi i quattro piatti","content":"Distribuisci in ogni piatto un quarto dei fagioli e del riso, 1 arepa, 1 striscia di chicharrón, 1 chorizo, un quarto della carne macinata e del platano, 1 uovo e 50 g di avocado. Aggiungi l’hogao restante a piacere e servi subito. Quantità, tempi e resa sono una proposta editoriale in attesa di conferma in cucina.","image_url":"/recetas/receta-de-bandeja-paisa/paso-10.webp","image_alt":"Bandeja paisa completa con fagioli, riso, arepa, carni, platano, uovo, avocado e hogao"}]},{"id":"5dd9ebf9-e855-53af-afae-5ffb6ad9a767","recipe_group_id":"8686de2f-500a-4c72-8f1c-1e9c0341e905","language":"ja","slug":"bandeja-paisa","public_path":"/ja/bandeja-paisa","total_time_minutes":675,"summary":"アンティオキア地方の料理を代表する具材を一皿に集めたバンデハ・パイサです。とろみのある赤いんげん豆、白いご飯、アレパ、牛ひき肉、カリッと焼いた豚皮付き肉、チョリソー、完熟プランテンのスライス、目玉焼き、アボカド、ホガオを盛り合わせます。\n\nたっぷりした4人分を想定しています。準備45分、加熱約150分、豆を浸す8–12時間を合わせ、全体では675–915分です。レシピカードには8時間の浸水を含む最短の675分を表示しています。複数の調理作業は並行して行います。分量、時間、油の吸収量、出来上がり量は調理試作による確認前の提案です。","content_html":"<p>アンティオキア地方の料理を代表する具材を一皿に集めたバンデハ・パイサです。とろみのある赤いんげん豆、白いご飯、アレパ、牛ひき肉、カリッと焼いた豚皮付き肉、チョリソー、完熟プランテンのスライス、目玉焼き、アボカド、ホガオを盛り合わせます。</p><p>たっぷりした4人分を想定しています。準備45分、加熱約150分、豆を浸す8–12時間を合わせ、全体では675–915分です。レシピカードには8時間の浸水を含む最短の675分を表示しています。複数の調理作業は並行して行います。分量、時間、油の吸収量、出来上がり量は調理試作による確認前の提案です。</p>","steps":[{"title":"豆を浸す","content":"乾燥赤いんげん豆200 gを選別して洗います。たっぷりの冷水で覆い、冷蔵庫で8–12時間浸します。水を切り、浸水に使った水は捨てます。最短の合計675分には8時間の浸水を含みます。12時間浸す場合、全体で915分を見込んでください。","image_url":"/recetas/receta-de-bandeja-paisa/paso-01.webp","image_alt":"バンデハ・パイサ：浸水用の水で覆った乾燥赤いんげん豆"},{"title":"豆が柔らかくなるまで煮る","content":"水を切った豆を鍋に入れ、清潔な水1リットルを加えます。沸騰させ、泡を取り、火を中弱火に下げ、ふたを少し開けて90–120分煮ます。20分ごとに混ぜ、豆が水面から出たら熱湯を足します。形を保ちながら簡単につぶせる柔らかさになれば完了です。この段階ではトマトや塩を加えません。","image_url":"/recetas/receta-de-bandeja-paisa/paso-02.webp","image_alt":"バンデハ・パイサ：鍋でゆっくり煮ている赤いんげん豆"},{"title":"ホガオを作る","content":"豆を煮ている間に、フライパンで油のうち15 gを中火で温めます。みじん切りの玉ねぎ160 gを加えて5分加熱します。にんにく12 gとクミン1 gを加え、30秒混ぜます。トマト300 gと塩2 gを加え、とろみのあるソースになるまで12–15分煮ます。豆用に40 g取り分け、残りは盛り付け用に残します。","image_url":"/recetas/receta-de-bandeja-paisa/paso-03.webp","image_alt":"バンデハ・パイサ：フライパンの濃厚なトマトと玉ねぎのホガオ"},{"title":"豆を仕上げる","content":"豆が柔らかくなったら、取り分けたホガオ40 gと塩2 gを加えます。ふたをせず弱火で10分、混ぜながら煮て、煮汁がスプーンを薄く覆う濃さにします。乾きすぎた場合は熱湯を30 mlずつ加え、汁が多い場合はさらに煮詰めます。","image_url":"/recetas/receta-de-bandeja-paisa/paso-04.webp","image_alt":"バンデハ・パイサ：ホガオととろみのある煮汁で仕上げた赤いんげん豆"},{"title":"ご飯を炊く","content":"白米200 gを、水がほぼ透明になるまで洗います。鍋に米、水400 ml、塩2 gを入れます。沸騰したらふたをし、最弱火にして、ふたを開けずに15–18分炊きます。火を止めて10分蒸らし、フォークでほぐします。","image_url":"/recetas/receta-de-bandeja-paisa/paso-05.webp","image_alt":"バンデハ・パイサ：鍋で炊いてほぐした白いご飯"},{"title":"アレパを成形して焼く","content":"加熱処理済みコーンフラワー120 g、ぬるま湯240 ml、塩1 gを混ぜ、5分置きます。4等分し、直径約9 cm、厚さ1 cmの円盤状にして縁を整えます。薄く油を塗った鉄板で中弱火にし、片面6–8分ずつ、しっかりしてきつね色になるまで焼きます。","image_url":"/recetas/receta-de-bandeja-paisa/paso-06.webp","image_alt":"バンデハ・パイサ：鉄板で焼き色を付ける4枚の小さなアレパ"},{"title":"チチャロンを焼く","content":"皮付き豚バラ肉240 gを同じ大きさの4本に切り、肉を切り離さないよう皮に浅い切り込みを入れます。冷たいフライパンに肉と水60 mlを入れ、ふたをして中火で10分加熱します。ふたを取り、中弱火で20–30分、返しながら、水を蒸発させて脂を出します。皮がカリッとし、肉がこんがり焼け、中心が少なくとも71 °Cになったら取り出します。網で油を切り、脂は別に集めて排水口に流しません。","image_url":"/recetas/receta-de-bandeja-paisa/paso-07.webp","image_alt":"バンデハ・パイサ：フライパンのこんがりした豚皮付き肉"},{"title":"牛ひき肉とチョリソーを加熱する","content":"清潔なフライパンで油のうち10 gを温めます。牛ひき肉260 gと塩1 gを加え、中強火で7–9分、ほぐしながら、ピンク色の部分がなくなり71 °Cになるまで加熱します。取り出して温かく保ちます。同じフライパンで小さなチョリソー4本、合計200 gを10–12分、返しながら、中心が71 °Cになるまで加熱します。","image_url":"/recetas/receta-de-bandeja-paisa/paso-08.webp","image_alt":"バンデハ・パイサ：焼いた牛ひき肉と加熱中のチョリソー4本"},{"title":"プランテンと卵を焼く","content":"皮をむいた完熟プランテン400 gを斜めの薄切りにします。広いフライパンで残りの油を温め、中火で片面3–4分ずつ、黄金色で柔らかくなるまで焼き、網で油を切ります。同じフライパンで卵4個を1個ずつ3–4分、白身が完全に固まるまで焼きます。妊娠中の方、幼い子ども、高齢者、免疫機能が低下している方には、黄身も固くなるまで加熱します。","image_url":"/recetas/receta-de-bandeja-paisa/paso-09.webp","image_alt":"バンデハ・パイサ：黄金色のプランテンと白身が固まった目玉焼き"},{"title":"4皿に盛り付ける","content":"各皿に豆とご飯をそれぞれ4分の1、アレパ1枚、チチャロン1本、チョリソー1本、ひき肉とプランテンをそれぞれ4分の1、卵1個、アボカド50 gを盛ります。残りのホガオを好みで添え、すぐに出します。分量、時間、出来上がり量は、調理試作での確認を待つ編集上の提案です。","image_url":"/recetas/receta-de-bandeja-paisa/paso-10.webp","image_alt":"豆、ご飯、アレパ、肉、プランテン、卵、アボカド、ホガオを盛ったバンデハ・パイサ"}]},{"id":"36034df4-567d-5cc2-bb3a-8bf7520778b4","recipe_group_id":"8686de2f-500a-4c72-8f1c-1e9c0341e905","language":"pt","slug":"bandeja-paisa","public_path":"/pt/bandeja-paisa","total_time_minutes":675,"summary":"Esta bandeja paisa reúne em um só prato os componentes mais conhecidos da preparação de Antioquia: feijão vermelho encorpado, arroz branco, arepa, carne moída, torresmo, chorizo, fatias de banana-da-terra madura, ovo frito, abacate e hogao.\n\nA proposta rende 4 pratos fartos. São 45 minutos de preparo, cerca de 150 minutos de cozimento e 8–12 horas de molho do feijão: entre 675 e 915 minutos no total. A ficha mostra o mínimo de 675 minutos, incluindo 8 horas de molho; várias tarefas de cozinha são feitas em paralelo. Quantidades, tempos, absorção de óleo e rendimento aguardam confirmação por teste de cozinha.","content_html":"<p>Esta bandeja paisa reúne em um só prato os componentes mais conhecidos da preparação de Antioquia: feijão vermelho encorpado, arroz branco, arepa, carne moída, torresmo, chorizo, fatias de banana-da-terra madura, ovo frito, abacate e hogao.</p><p>A proposta rende 4 pratos fartos. São 45 minutos de preparo, cerca de 150 minutos de cozimento e 8–12 horas de molho do feijão: entre 675 e 915 minutos no total. A ficha mostra o mínimo de 675 minutos, incluindo 8 horas de molho; várias tarefas de cozinha são feitas em paralelo. Quantidades, tempos, absorção de óleo e rendimento aguardam confirmação por teste de cozinha.</p>","steps":[{"title":"Deixe o feijão de molho","content":"Escolha e lave 200 g de feijão vermelho seco. Cubra com bastante água fria e deixe 8–12 horas na geladeira. Escorra e descarte a água do molho. O total mínimo de 675 minutos inclui 8 horas de molho; com 12 horas de molho, calcule 915 minutos no total.","image_url":"/recetas/receta-de-bandeja-paisa/paso-01.webp","image_alt":"Bandeja paisa: feijão vermelho seco coberto com água para o molho"},{"title":"Cozinhe o feijão até ficar macio","content":"Coloque o feijão escorrido em uma panela com 1 litro de água limpa. Leve à fervura, retire a espuma, abaixe para fogo médio-baixo e cozinhe com a tampa parcialmente aberta por 90–120 minutos. Mexa a cada 20 minutos e acrescente água quente se os grãos deixarem de ficar cobertos. Estão prontos quando amassam facilmente, mas mantêm o formato; ainda não acrescente tomate nem sal.","image_url":"/recetas/receta-de-bandeja-paisa/paso-02.webp","image_alt":"Bandeja paisa: feijão vermelho cozinhando suavemente na panela"},{"title":"Prepare o hogao","content":"Enquanto o feijão cozinha, aqueça 15 g do óleo em uma frigideira em fogo médio. Junte 160 g de cebola picada e cozinhe 5 minutos. Acrescente 12 g de alho picado e 1 g de cominho; mexa 30 segundos. Junte 300 g de tomate picado e 2 g de sal. Cozinhe 12–15 minutos até obter um molho espesso. Reserve 40 g para o feijão e guarde o restante para servir.","image_url":"/recetas/receta-de-bandeja-paisa/paso-03.webp","image_alt":"Bandeja paisa: hogao espesso de tomate e cebola na frigideira"},{"title":"Finalize o feijão","content":"Quando o feijão estiver macio, junte os 40 g de hogao reservados e 2 g de sal. Cozinhe destampado por 10 minutos em fogo baixo, mexendo, até o caldo cobrir a colher. Se estiver muito seco, acrescente água quente de 30 em 30 ml; se estiver com muito caldo, prolongue a redução.","image_url":"/recetas/receta-de-bandeja-paisa/paso-04.webp","image_alt":"Bandeja paisa: feijão vermelho finalizado com hogao e caldo encorpado"},{"title":"Cozinhe o arroz","content":"Lave 200 g de arroz branco até a água ficar quase transparente. Coloque em uma panela com 400 ml de água e 2 g de sal. Leve à fervura, tampe, abaixe ao mínimo e cozinhe 15–18 minutos sem destampar. Desligue e deixe descansar 10 minutos; solte os grãos com um garfo.","image_url":"/recetas/receta-de-bandeja-paisa/paso-05.webp","image_alt":"Bandeja paisa: arroz branco cozido e soltinho na panela"},{"title":"Modele e asse as arepas","content":"Misture 120 g de farinha de milho pré-cozida com 240 ml de água morna e 1 g de sal. Descanse 5 minutos. Divida em 4 porções, forme discos de cerca de 9 cm de diâmetro e 1 cm de espessura e alise as bordas. Asse em chapa levemente untada em fogo médio-baixo por 6–8 minutos de cada lado, até ficarem firmes e dourados.","image_url":"/recetas/receta-de-bandeja-paisa/paso-06.webp","image_alt":"Bandeja paisa: quatro arepas pequenas dourando na chapa"},{"title":"Doure o torresmo","content":"Corte 240 g de barriga de porco com pele em 4 tiras iguais e faça cortes rasos na pele sem separar os pedaços. Coloque em uma frigideira fria com 60 ml de água, tampe e cozinhe 10 minutos em fogo médio. Destampe e continue 20–30 minutos em fogo médio-baixo, virando, enquanto a água evapora e a gordura derrete. Retire quando a pele estiver crocante, a carne dourada e o centro atingir pelo menos 71 °C. Escorra em grade; recolha a gordura separadamente, sem despejar no ralo.","image_url":"/recetas/receta-de-bandeja-paisa/paso-07.webp","image_alt":"Bandeja paisa: tiras de torresmo douradas e crocantes na frigideira"},{"title":"Cozinhe a carne e os chorizos","content":"Aqueça 10 g do óleo em uma frigideira limpa. Junte 260 g de carne moída e 1 g de sal; cozinhe 7–9 minutos em fogo médio-alto, soltando a carne, até não haver partes rosadas e atingir 71 °C. Retire e mantenha quente. Na mesma frigideira, cozinhe 4 chorizos pequenos, 200 g no total, por 10–12 minutos, virando, até atingirem 71 °C no centro.","image_url":"/recetas/receta-de-bandeja-paisa/paso-08.webp","image_alt":"Bandeja paisa: carne moída dourada e quatro chorizos em cozimento"},{"title":"Frite a banana-da-terra e os ovos","content":"Corte 400 g de banana-da-terra madura sem casca em fatias diagonais. Aqueça o óleo restante em uma frigideira larga e frite as fatias em fogo médio por 3–4 minutos de cada lado, até ficarem douradas e macias; escorra em grade. Na mesma frigideira, frite 4 ovos, um de cada vez, por 3–4 minutos, até a clara ficar totalmente firme. Para gestantes, crianças pequenas, idosos ou pessoas imunodeprimidas, cozinhe também a gema até ficar firme.","image_url":"/recetas/receta-de-bandeja-paisa/paso-09.webp","image_alt":"Bandeja paisa: banana-da-terra dourada e ovos fritos com claras firmes"},{"title":"Monte os quatro pratos","content":"Distribua em cada prato um quarto do feijão e do arroz, 1 arepa, 1 tira de torresmo, 1 chorizo, um quarto da carne moída e da banana-da-terra, 1 ovo e 50 g de abacate. Acrescente o hogao restante a gosto e sirva imediatamente. Quantidades, tempos e rendimento são uma proposta editorial aguardando confirmação em cozinha.","image_url":"/recetas/receta-de-bandeja-paisa/paso-10.webp","image_alt":"Bandeja paisa completa com feijão, arroz, arepa, carnes, banana-da-terra, ovo, abacate e hogao"}]}]$payload$::jsonb;
 e constant jsonb := $before$[{"id":"c50bd0e3-f8cd-59d6-ad26-8d357e17b95c","language":"de","row_md5":"05eb9ec48b970561d9c76e9ac0fc906f","total_time_minutes":195,"created_at":"2026-10-08 11:35:14.366858+00","published_at":"2026-10-08 11:35:14.366858+00","public_path":"/de/bandeja-paisa-kolumbianischer-teller","slug":"bandeja-paisa-kolumbianischer-teller","source_url":null},{"id":"6857b59b-7f19-5cd9-a3cc-930700c6932e","language":"en","row_md5":"a2f5a0d1fc0e34c48edb53163798cd0a","total_time_minutes":195,"created_at":"2026-10-08 11:35:14.366858+00","published_at":"2026-10-08 11:35:14.366858+00","public_path":"/en/bandeja-paisa-colombian-platter","slug":"bandeja-paisa-colombian-platter","source_url":null},{"id":"835f1de3-70b7-4d41-a9ff-1695b7ae21fc","language":"es","row_md5":"d9fdf6a7e423331aa5c3cfe355c221af","total_time_minutes":195,"created_at":"2026-09-23 20:50:30.015432+00","published_at":"2026-09-23 20:50:30.015432+00","public_path":"/receta-de-bandeja-paisa","slug":"receta-de-bandeja-paisa","source_url":"https://manualdecocina.com/receta-de-bandeja-paisa/"},{"id":"647e43c1-a9d5-5fd4-8b6d-fabdada6a31c","language":"fr","row_md5":"5e668a3fb3f1db3bd33a61b883280602","total_time_minutes":195,"created_at":"2026-10-08 11:35:14.366858+00","published_at":"2026-10-08 11:35:14.366858+00","public_path":"/fr/bandeja-paisa-assiette-colombienne","slug":"bandeja-paisa-assiette-colombienne","source_url":null},{"id":"af83a975-46d3-5abf-adc0-5017f45b69f8","language":"it","row_md5":"74b352c1e034805168e13083b97deafa","total_time_minutes":195,"created_at":"2026-10-08 11:35:14.366858+00","published_at":"2026-10-08 11:35:14.366858+00","public_path":"/it/bandeja-paisa-piatto-colombiano","slug":"bandeja-paisa-piatto-colombiano","source_url":null},{"id":"5dd9ebf9-e855-53af-afae-5ffb6ad9a767","language":"ja","row_md5":"49df726d87817c6b51f442dd35992e19","total_time_minutes":195,"created_at":"2026-10-08 11:35:14.366858+00","published_at":"2026-10-08 11:35:14.366858+00","public_path":"/ja/bandeja-paisa","slug":"bandeja-paisa","source_url":null},{"id":"36034df4-567d-5cc2-bb3a-8bf7520778b4","language":"pt","row_md5":"5acc669497522b138780c21ad5958fe0","total_time_minutes":195,"created_at":"2026-10-08 11:35:14.366858+00","published_at":"2026-10-08 11:35:14.366858+00","public_path":"/pt/bandeja-paisa","slug":"bandeja-paisa","source_url":null}]$before$::jsonb;
 outside_checksum text;
 n int;
begin
 perform r.id from public.recipes r where recipe_group_id='8686de2f-500a-4c72-8f1c-1e9c0341e905' order by id for update;
 if jsonb_array_length(j)<>7 or jsonb_array_length(e)<>7
    or (select count(*) from public.recipes where recipe_group_id='8686de2f-500a-4c72-8f1c-1e9c0341e905' and published)<>7 then
   raise exception 'Bandeja-paisa seven-language publication state diverged';
 end if;
 if not exists(select 1 from jsonb_populate_recordset(null::public.recipes,j) x
  left join public.recipes r on r.id=x.id where r.id is null
   or r.total_time_minutes is distinct from x.total_time_minutes
   or r.summary is distinct from x.summary or r.content_html is distinct from x.content_html
   or r.steps is distinct from x.steps) then
   raise notice 'Matching time correction already applied; no mutation'; return;
 end if;
 if exists(select 1 from jsonb_array_elements(e) b left join public.recipes r on r.id=(b->>'id')::uuid
  where r.id is null or md5(to_jsonb(r)::text)<>b->>'row_md5') then
  raise exception 'Bandeja-paisa row changed since correction baseline';
 end if;
 select md5(string_agg(md5(to_jsonb(r)::text),',' order by id)) into outside_checksum
  from public.recipes r where recipe_group_id<>'8686de2f-500a-4c72-8f1c-1e9c0341e905';
 update public.recipes r set total_time_minutes=x.total_time_minutes,summary=x.summary,
  content_html=x.content_html,steps=x.steps
  from jsonb_populate_recordset(null::public.recipes,j) x
  where r.id=x.id and r.recipe_group_id=x.recipe_group_id and r.language=x.language
   and r.public_path=x.public_path and r.slug=x.slug and r.published;
 get diagnostics n=row_count;
 if n<>7 then raise exception 'Expected seven time corrections, got %',n; end if;
 if exists(select 1 from jsonb_array_elements(e) b left join public.recipes r on r.id=(b->>'id')::uuid
  where r.id is null or not r.published or r.slug<>b->>'slug' or r.public_path<>b->>'public_path'
   or r.created_at is distinct from (b->>'created_at')::timestamptz
   or r.published_at is distinct from (b->>'published_at')::timestamptz
   or r.source_url is distinct from b->>'source_url' or r.total_time_minutes<>675) then
  raise exception 'Identity, date or corrected total invariant failed';
 end if;
 if outside_checksum is distinct from (select md5(string_agg(md5(to_jsonb(r)::text),',' order by id))
  from public.recipes r where recipe_group_id<>'8686de2f-500a-4c72-8f1c-1e9c0341e905') then
  raise exception 'Recipe outside correction changed';
 end if;
end $correction$;
commit;
